export const SLOT_ACCEPTED = 0;
export const SLOT_REJECTED = 1;
export const SLOT_BYTES = 2;
export const SLOT_INFLIGHT = 3;
export const SLOT_COUNT = 4;

export function createStatsBuffer(): SharedArrayBuffer {
  return new SharedArrayBuffer(SLOT_COUNT * BigInt64Array.BYTES_PER_ELEMENT);
}

export class IngestStats {
  private readonly view: BigInt64Array;

  constructor(buffer: SharedArrayBuffer) {
    this.view = new BigInt64Array(buffer);
  }

  accepted(bytes: number): void {
    Atomics.add(this.view, SLOT_ACCEPTED, 1n);
    this.view[SLOT_BYTES] += BigInt(bytes);
  }

  rejected(): void {
    Atomics.add(this.view, SLOT_REJECTED, 1n);
  }

  begin(): void {
    Atomics.add(this.view, SLOT_INFLIGHT, 1n);
  }

  end(): void {
    Atomics.sub(this.view, SLOT_INFLIGHT, 1n);
  }

  snapshot() {
    return {
      accepted: Atomics.load(this.view, SLOT_ACCEPTED),
      rejected: Atomics.load(this.view, SLOT_REJECTED),
      bytes: Atomics.load(this.view, SLOT_BYTES),
      inflight: Atomics.load(this.view, SLOT_INFLIGHT),
    };
  }

  drainCounters() {
    return {
      accepted: Atomics.exchange(this.view, SLOT_ACCEPTED, 0n),
      rejected: Atomics.exchange(this.view, SLOT_REJECTED, 0n),
      bytes: Atomics.exchange(this.view, SLOT_BYTES, 0n),
    };
  }
}

import { parentPort, workerData } from "worker_threads";
import { IngestStats } from "./ingestStats";

interface TelemetryFrame {
  deviceId: string;
  ts: number;
  readings: Record<string, number>;
}

const stats = new IngestStats(workerData.statsBuffer as SharedArrayBuffer);

function decode(raw: Buffer): TelemetryFrame | null {
  try {
    const frame = JSON.parse(raw.toString("utf8"));
    if (typeof frame.deviceId !== "string" || typeof frame.ts !== "number") return null;
    if (typeof frame.readings !== "object" || frame.readings === null) return null;
    return frame as TelemetryFrame;
  } catch {
    return null;
  }
}

parentPort!.on("message", (raw: Buffer) => {
  stats.begin();
  try {
    const frame = decode(raw);
    if (!frame) {
      stats.rejected();
      return;
    }
    parentPort!.postMessage({ type: "frame", frame });
    stats.accepted(raw.byteLength);
  } finally {
    stats.end();
  }
});

import { Worker } from "worker_threads";
import { createStatsBuffer, IngestStats } from "./ingestStats";

export interface MetricsSink {
  report(name: string, value: number, tags?: Record<string, string>): void;
}

export class IngestPool {
  private readonly workers: Worker[] = [];
  private readonly statsBuffer = createStatsBuffer();
  private readonly stats = new IngestStats(this.statsBuffer);
  private next = 0;
  private flushTimer?: NodeJS.Timeout;

  constructor(private readonly size: number, private readonly sink: MetricsSink) {}

  start(onFrame: (frame: unknown) => void): void {
    for (let i = 0; i < this.size; i++) {
      const w = new Worker(new URL("./ingestWorker.js", import.meta.url), {
        workerData: { statsBuffer: this.statsBuffer },
      });
      w.on("message", (msg) => {
        if (msg.type === "frame") onFrame(msg.frame);
      });
      this.workers.push(w);
    }
    this.flushTimer = setInterval(() => this.flush(), 10_000);
  }

  submit(raw: Buffer): void {
    const w = this.workers[this.next];
    this.next = (this.next + 1) % this.workers.length;
    w.postMessage(raw);
  }

  private flush(): void {
    const d = this.stats.drainCounters();
    const inflight = this.stats.snapshot().inflight;
    this.sink.report("telemetry.frames.accepted", Number(d.accepted));
    this.sink.report("telemetry.frames.rejected", Number(d.rejected));
    this.sink.report("telemetry.bytes", Number(d.bytes));
    this.sink.report("telemetry.inflight", Number(inflight));
  }

  async stop(): Promise<void> {
    if (this.flushTimer) clearInterval(this.flushTimer);
    this.flush();
    await Promise.all(this.workers.map((w) => w.terminate()));
  }
}
